import { Box, Button, styled } from "@mui/material";
import { useNavigate } from 'react-router-dom';
import { PATH_SERVICES } from 'src/routes/path';
import { useTranslation } from 'react-i18next';

// -------------------------------------------------------------------------

const Container = styled(Box)(({ theme }) => ({
  position: 'relative',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  width: '100%',
  height: `calc(100vh - ${theme.mixins.toolbar.minHeight}px)`,
  '@supports (height: 100dvh)': {
    height: `calc(100dvh - ${theme.mixins.toolbar.minHeight}px)`,
  },
  [theme.breakpoints.up('sm')]: {
    height: 'calc(100vh - 64px)',
    '@supports (height: 100dvh)': {
      height: 'calc(100dvh - 64px)',
    },
  },
  overflow: 'hidden',
}));

const Title = styled(Box)(({ theme }) => ({
  width: '100%',
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  float: 'left',
  position: 'absolute',
  zIndex: 1000,
  backgroundColor: 'rgba(0, 0, 0, 0.6)',
  color: theme.palette.common.white,
  fontWeight: 'bold',
  borderRadius: 3,
  padding: theme.spacing(4),
  [theme.breakpoints.down('sm')]: {
    padding: theme.spacing(2),
  },
}));

const BoxStyled = styled(Box)(() => ({
  position: 'absolute',
  inset: 0,
  width: '100%',
  height: '100%',
  objectFit: 'cover',
  display: 'block',
}));

const ButtonServices = styled(Button)(({ theme }) => ({
  marginTop: theme.spacing(6),
  border: '4px solid',
  borderRadius: 0,
  padding: `${theme.spacing(0.5)} ${theme.spacing(8)}`,
  fontSize: '1rem',
  letterSpacing: 2,
  '&:hover': {
    background: theme.palette.common.white,
    color: theme.palette.common.black,
    border: `4px solid ${theme.palette.common.white}`
  }
}));

// -------------------------------------------------------------------------

export default function IntroImage() {
  const navigate = useNavigate();
  const { t } = useTranslation();

  const handleOpenServices = () => {
    navigate(PATH_SERVICES.index);
  };

  return(
    <Container>
      <Title>
        <Box component="img" src={process.env.PUBLIC_URL + '/static/logo-white.png'} alt="BLACKSTOCK" sx={{ width: { xs: 280, sm: 400 } }} />
        <ButtonServices variant="outlined" color="inherit" onClick={handleOpenServices}>
          {t('services.title')}
        </ButtonServices>
      </Title>
      <BoxStyled
        component="img" 
        src='/static/skyscraper.png'
        alt="logo"
      />
    </Container>
  );
};
